// Calc engine adapter: runs the vendored rust-math-engine WASM build
// (server/office/calc-engine.mjs, generated by scripts/build-calc-engine.mjs)
// over a parsed workbook model and projects computed values per cell.
//
// The engine is loaded lazily and only once. recalcWorkbook() returns null
// when the engine cannot run the workbook (unsupported sheet names, huge
// models) — callers fall back to the file's cached values and warn.
import { loadCalcEngine } from "./calc-engine.mjs";

let enginePromise;
const engine = () => (enginePromise ??= loadCalcEngine());

// Synchronous WASM recalculation blocks the event loop; keep the evaluated
// model small enough that a get/save round trip stays interactive.
export const RECALC_MAX_CELLS = 50000;

const scalar = (cell) => {
  if (!cell || cell.kind === "blank") return {};
  if (cell.kind === "number" || cell.kind === "boolean" || cell.kind === "text")
    return { value: cell.value };
  if (cell.kind === "error") return { value: cell.code, error: true };
  if (cell.kind === "array") {
    const first = cell.values?.[0]?.[0];
    return scalar(first ?? { kind: "error", code: "#SPILL!" });
  }
  return {};
};

/**
 * Evaluate every stored cell of the workbook model.
 * Returns { sheets: Map<sheetName, Map<ref, {value?, error?}>>, evaluated }
 * or null when the engine is unavailable or the model is too large.
 */
export async function recalcWorkbook(workbook) {
  let cells = 0;
  for (const sheet of workbook.sheets) cells += sheet.cells.size;
  if (cells > RECALC_MAX_CELLS) return null;
  let calc;
  try {
    calc = await engine();
  } catch {
    return null;
  }
  const wb = new calc.WasmWorkbook();
  try {
    // The engine always starts with an empty "Sheet1"; reuse it for a sheet
    // actually named Sheet1 and add every other sheet by its real name so
    // cross-sheet references resolve. When the first sheet is not "Sheet1"
    // the engine's empty Sheet1 stays unused (a formula referencing a
    // nonexistent Sheet1 yields an error value, matching Excel).
    const sheets = [];
    for (const [index, sheet] of workbook.sheets.entries()) {
      const name = index === 0 && sheet.name === "Sheet1" ? "Sheet1" : sheet.name;
      if (name !== "Sheet1" || index !== 0) {
        try {
          wb.addSheet(name);
        } catch {
          return null;
        }
      }
      sheets.push({ model: sheet, name });
    }
    for (const { model: sheet, name } of sheets) {
      for (const [ref, cell] of sheet.cells) {
        try {
          if (cell.formula !== undefined && cell.formula !== "")
            wb.setCell(name, ref, `=${cell.formula}`);
          else if (
            typeof cell.value === "number" ||
            typeof cell.value === "boolean" ||
            typeof cell.value === "string"
          )
            wb.setCellValue(name, ref, cell.value);
        } catch {
          // A formula the engine cannot parse keeps its cached value.
        }
      }
    }
    const report = wb.recalculate();
    const bySheet = new Map();
    for (const { model: sheet, name } of sheets) {
      const values = new Map();
      for (const ref of sheet.cells.keys()) {
        try {
          values.set(ref, scalar(wb.getValue(name, ref)));
        } catch {
          // Unreadable cells keep their cached values in the projection.
        }
      }
      bySheet.set(sheet.name, values);
    }
    return { sheets: bySheet, evaluated: report?.evaluated?.length ?? 0 };
  } catch {
    return null;
  } finally {
    wb.free();
  }
}
